update_rule.pseudocode:
if t == 0:
  N = population_size
  if social_network_type == 'small_world':
    G = WattsStrogatz(N, k=avg_degree, beta=rewiring_prob, seed=network_seed)
  elif social_network_type == 'erdos_renyi':
    p = avg_degree/(N-1)
    G = ErdosRenyi(N, p, seed=network_seed)
  elif social_network_type == 'scale_free':
    G = BarabasiAlbert(N, m=max(1, avg_degree//2), seed=network_seed)
  assign neighbors to each Person from G adjacency
  emit signals.network.graph = G and signals.person.neighbors_assigned = true
else:
  no-op
